<template>
	<div class="mainHotImg">
		<div class="titleHotImg">
			<div class="titleHotImg1">
				<p><i class="el-icon-s-data"></i>热度图片列表</p>
			</div>
			<div class="titleHotImg2">
				<el-button type="primary" @click="goAdd()"><i class="el-icon-document">添加新的热度图片</i></el-button>
				<p>类型自定义,获取时指定类型 1=轮播图 2=广告图</p>
			</div>
		</div>
		
		<el-table style="width: 100%;margin-top: 10px;" :data="hotimgs"
			:header-cell-style="{color: '#FFFFFF',background:'#AAAAAA'}">
			<el-table-column prop="id" label="描述">
			</el-table-column>
			<el-table-column prop="memo" label="类型">
			</el-table-column>
			<el-table-column prop="hot" label="优先级">
			</el-table-column>
			<el-table-column label="图片">
				<template slot-scope="scope">
					<img :src="'http://127.0.0.1:80/api/public/showimg/'+scope.row.picture" style="width: 70px;height: 70px;">
				</template>
			</el-table-column>
			<el-table-column label="操作">
				<template slot-scope="scope">
					<el-button type="primary" @click="goUpdate(scope.row)">修改</el-button>
				</template>
			</el-table-column>
			<el-table-column label="操作">
				<template slot-scope="scope">
					<el-button  type="danger" @click="remove(scope.row.id)">删除</el-button>
				</template>
			</el-table-column>
		</el-table>
		</div>
</template>

<script>
	export default {
		data() {
			return {
				hotimgs:[]
			};
		},
		computed: {
			
		},
		methods:{
			goAdd(){
				this.$router.push({
					name:"hmanage",
					params:{
					add:true}
				})
			},
			goUpdate(hot){
				this.$router.push({
					name:"hmanage",
					params:{hot:hot,
					add:false}
				})
			},
			remove(id){
				var that = this
				this.$get(
					"/api/adm/hot/remove",
					{params:{id:id}}
				).then(function(resp) {
					that.$get("/api/adm/hot/findAll")
						.then((resp) => {
							this.hotimgs = resp.data.data
							})
				})
			}
		},
		created() {
			var that = this;
			this.$get("/api/public/hot/findAll")
				.then((resp) => {
					this.hotimgs = resp.data.data
					})
		}
	}
</script>

<style>
	.mainHotImg{
		margin-left: 4px;
		width: 100%;
	}
	
	.titleHotImg{
		display: flex;
	}
	
	.titleHotImg1{
		margin-top: 10px;
		height: 40px;
		background-color: #d9ecff;
		width: 40%;
		display: flex;
		align-items: center;
	}
	
	.titleHotImg2{
		margin-top: 10px;
		height: 40px;
		background-color: #d9ecff;
		width: 60%;
		display: flex;
		align-items: center;
	}
	
	.titleHotImg1 p{
		color: #409EFF;
	}
	
	.titleHotImg2 p{
		margin-left: 10vw;
		color: #409EFF;
		overflow: hidden;
		white-space: nowrap;
	}
	
	
</style>