<template>
	<div>
		<div>
			<div style="text-align: center;margin-top: 15px;"><i class="el-icon-s-order "
					style="color: blueviolet;"></i><span style="color: #adc1c4;font-weight: 600;">我的购物车清单</span></div>
			<hr>

			<el-table style="width: 90%;margin-top: 10px;margin-left: 5%;" :data="myCart" border>
				<el-table-column label="图片">
					<template slot-scope="scope">
						<img :src="'http://127.0.0.1:80/api/public/showimg/'+scope.row.book.pic"
							style="width: 70px;height: 70px;">
					</template>
				</el-table-column>
				<el-table-column prop="book.name" label="商品名称">
				</el-table-column>
				<el-table-column prop="book.price" label="商品价钱">
				</el-table-column>
				<el-table-column label="商品数量" width="200">
					<template slot-scope="scope">
						<el-input type="number" v-model="scope.row.num"  :min="1"></el-input>
					</template>
				</el-table-column>
				<el-table-column label="商品总价">
					<template slot-scope="scope">
						<p>{{scope.row.num*scope.row.book.price}}</p>
					</template>
				</el-table-column>
				<el-table-column label="复选框">
					<template slot-scope="scope">
						<el-checkbox @change="clickCart(scope.row)" v-model="scope.row.checked"></el-checkbox>
					</template>
				</el-table-column>
			</el-table>
			<div style="height: 14px;background-color:gainsboro;width: 90%;margin-left: 5%;"></div>
			<div style="height: 50px;width: 90%;margin-left: 5%;">
				<div style="width: 25%;height: 50px;margin-left: auto;display: flex;">
					<p style="white-space: nowrap;">总价:&nbsp;&nbsp;&nbsp;</p>
					<p>{{totalPrice}}￥</p>
					<el-button @click="goOrder()"
					style="background-color: lightcoral;color: white;margin-left: auto;">去下单</el-button>
				</div>
			</div>
			<div style="height: 14px;background-color:gainsboro;width: 90%;margin-left: 5%;"></div>
		</div>
	</div>
</template>

<script>
	export default {
		data() {
			return {
				myCart: [],
				checkCart: [],
				totalPrice: 0,
				idList:[]
			};
		},
		computed: {
			totalNumber() {
				let total = 0;
				for (let i = 0; i < this.myCart.length; i++) {
					total += this.myCart[i].num * this.myCart[i].book.price;
				}
				return total;
			}
		},
		methods: {
			goOrder(){
				if(this.checkCart != null){
				for(let i=0;i<this.checkCart.length;i++){
					if(this.checkCart[i].book.stock-this.checkCart[i].num<0){
						this.$message({
							type:'warning',
							message:"库存不足"
						})
						return
					}
				}
				this.$router.push({
					name:"carttoorder",
					params:{
						checkCart:this.checkCart
					}
				})
				}
			},
			clickCart(cart) {
				if (cart.checked == true) {
					this.checkCart.push(cart)
				}
				if (cart.checked == false) {
					let index = this.checkCart.indexOf(cart)
					if (index != -1) {
						this.checkCart.splice(index, 1)
					}
				}
				this.totalPrice = 0
				for (let i = 0; i < this.checkCart.length; i++) {
					this.totalPrice += this.checkCart[i].num * this.checkCart[i].book.price
				}
			}
		},
		created() {
			this.$get("/api/userc/cart/findAll")
				.then((resp) => {
					this.myCart = resp.data.data
				})
		}
	}
</script>

<style>
	hr {
		width: 90%;
		border: 1px solid skyblue;
	}
</style>