<template>
	<div>
		<div style=" display: flex; justify-content: space-around;">
			<div><img src="../../../assets/105742_300.png" style="width: 15vw; height: 15vh;"></div>
			<div style="margin-top: 60px;"><el-input placeholder="请输入内容" v-model="key"
					style="width: 300px;"></el-input><el-button type="danger" icon="el-icon-search"
					@click="doSearch()">搜索</el-button></div>
			<div><el-button type="danger" icon="el-icon-shopping-cart-2" style="margin-top: 60px;">我的购物车</el-button>
			</div>
		</div>
		<div style="width: 80%;margin-left: 100px;display: flex;">
			<el-link @click="back()" style="font-size: 16.5px;" id="change2" :underline="false">返回商品列表页</el-link>
			<span style="margin-left: auto;color: #f8987a;">同类商品推荐</span>
		</div>
		<hr style="width: 90%;
		border: 1px solid orange;">
		<div style="margin-left: 50px;margin-top: 20px;display: flex;">
			<div>
				<img :src="`http://127.0.0.1/api/public/showimg/${book.pic}`" style="width: 35vw;height: 45vh;" />
			</div>

			<div style="margin-left: 3%;">
				<table>
					<tr>
						<td colspan="2">
							<p style="color: lightgray;font-weight: 600;font-size: 22px;white-space: nowrap;">
								{{book.name}}
							</p>
						</td>
					</tr>
					<tr>
						<td>类别:</td>
						<td v-if="book.type" style="white-space: nowrap;">{{book.type.name}}</td>
						<td v-else>暂无类别</td>
					</tr>
					<tr>
						<td>出版社:</td>
						<td style="white-space: nowrap;">{{book.maker}}</td>
					</tr>
					<tr>
						<td>作者:</td>
						<td style="white-space: nowrap;">{{book.author}}</td>
					</tr>
					<tr>
						<td>出版时间:</td>
						<td style="white-space: nowrap;">{{formatDate(book.tmake)}}</td>
					</tr>
					<tr>
						<td>出版号:</td>
						<td style="white-space: nowrap;">{{book.sn}}</td>
					</tr>
					<tr>
						<td>价格:</td>
						<td style="white-space: nowrap;">{{book.price}}</td>
					</tr>
					<tr>
						<td>促销价:</td>
						<td></td>
					</tr>
					<tr>
						<td>库存数:</td>
						<td style="white-space: nowrap;">{{book.stock}}</td>
					</tr>
					<tr>
						<td>销售量:</td>
						<td style="white-space: nowrap;">{{book.salenum}}</td>
					</tr>
					<tr>
						<td rowspan="2"><el-button @click="buyBook(book.id)" style="color: white;background-color: #f8987a;
					"><i class="el-icon-shopping-cart-2"></i>加入购物车</el-button></td>
					</tr>
				</table>
			</div>

			<div style="margin-left: 19%;margin-top: 10px;">
				<div v-for="i in TypeBookList" style="display: flex;margin-top: 5px;">
					<div>
						<img :src="`http://127.0.0.1/api/public/showimg/${i.pic}`" style="width: 50px;height: 50px;" />
					</div>
					<div style="width: 150px;">
						<p style="font-size: 5px;font-weight: 600;" id="change3" @click="goBookMessage(i.id)">{{i.name}}
						</p>
						<p style="font-size: 5px;">{{i.maker}}</p>
					</div>
					<div style="width: 100px;">
						<p style="font-size: 5px;font-weight: 600;margin-left: 10px;">￥{{i.price}}</p>
						<p style="font-size: 5px;margin-left: 10px;">{{i.author}}</p>
					</div>
				</div>
			</div>

		</div>
		<div style="width: 80%;margin-left: 100px;display: flex;">
			<p style="color: #f8987a;">商品详情</p>
		</div>
		<hr style="width: 90%;
		border: 1px solid orange;">
		<div style="width: 80%;margin-left: 100px;display: flex;">
			<p>{{book.info}}</p>
		</div>
		<div style="width: 80%;margin-left: 100px;">
			<p style="color:blueviolet;">商品评价</p>
			<div style="display: flex;">
				<div>
					<el-avatar :src="`https://cube.elemecdn.com/3/7c/3ea6beec64369c2642b92c6726f1epng.png`" :size="65"
						v-if="user == null"></el-avatar>
					<el-avatar size="large" :src="`http://127.0.0.1/api/public/showimg/${user.img}`" :size="65"
						v-if="user != null"></el-avatar>
				</div>
				<div style="width: 100%;">
					<el-input type="textarea" style="margin-left: 10px;width: 80%;"
						v-model="comment.content"></el-input>
					<div style="display: flex;margin-top: 10px;margin-left: 20px;">
						<span style="color: blueviolet;">打分:</span>
						<el-rate v-model="comment.rate"></el-rate>
						<el-button type="primary" size="mini" @click="addComment()"
							style="margin-left: 20px;margin-top: -5px;">发布</el-button>
					</div>
				</div>
			</div>
		</div>
		<hr style="width: 90%;
		border: 1px solid skyblue;">
		<div style="width: 80%;margin-left: 100px;">
			<div v-for="i in comments">
				<div style="display: flex;">
					<div>
						<el-avatar el-avatar size="large" :src="`http://127.0.0.1/api/public/showimg/${i.img}`"
							:size="50"></el-avatar>
					</div>
					<div>
						<div style="display: flex;">
							<span>&nbsp;&nbsp;{{i.nickname}}</span>
							<span>&nbsp;&nbsp;{{formatDate(i.tpost)}}&nbsp;&nbsp;</span>
							<el-rate v-model="i.rate" disabled></el-rate>
						</div>
						<div style="margin-top: 5px;">
							<span>&nbsp;&nbsp;{{i.content}}</span>
						</div>
					</div>
				</div>
				<div style="height: 30px;"></div>
			</div>
		</div>
	</div>
</template>

<script>
	import {
		mapActions,
		mapState
	} from 'vuex'
	export default {
		data() {
			return {
				key: "",
				bookid: this.$route.query.bookid,
				book: {},
				TypeBookList: [],
				value1: null,
				comment: {},
				comments: []
			};
		},
		computed: {
			...mapState('user', ['user']),
		},
		methods: {
			buyBook(bookid){
				var that = this
				if(this.user == null){
					this.$message({
						type: 'error',
						message: "未登录,请先登录"
					})
				}else{
				this.$get(
					`/api/public/cart/addCart/${bookid}/${this.user.id}`
				).then(function(resp) {
					if(resp.data.code == 200){
					that.$message({
						type: 'success',
						message: resp.data.msg
					})
					}else{
						that.$message({
							type: 'error',
							message: resp.data.msg
						})
					}
				}).catch(function(error) {
					
				})
				}
			},
			doSearch() {
				this.$router.push({
					path: "/user/homebooklist",
					query: {
						key: this.key
					}
				})
			},
			goBookMessage(id) {
				this.bookid = id
				this.getBook()
				this.getComment()
			},
			addComment() {
				var that = this
				if (this.user == null) {
					this.$message({
						type: 'warning',
						message: "未登录,请登录后再尝试发表评论"
					})
				}else if(this.user.role =='adm'){
					this.$message({
						type: 'warning',
						message: "只有买家可以发表评论"
					})
				} else {
					this.$get("/api/userc/my/findOne", {
						params: {
							id: this.user.id
						}
					}).then((resp) => {
						this.comment.uid = resp.data.data.id
						this.comment.nickname = resp.data.data.nickname
						this.comment.img = resp.data.data.img
						this.comment.bookid = this.bookid
						this.$postx(
							"/api/userc/comment/add",
							this.comment
						).then(function(resp) {
							that.$message({
								type: 'success',
								message: "评论发表成功"
							})
							that.getComment()
						})
					})

				}
			},
			getComment() {
				this.$get("/api/userc/comment/findAll", {
						params: {
							bookid: this.bookid
						}
					})
					.then((resp) => {
						this.comments = resp.data.data
						
					})
			},
			getBook() {
				this.$get("/api/public/book/findOne", {
						params: {
							id: this.bookid
						}
					})
					.then((resp) => {
						this.book = resp.data.data
						this.findAllBookByType()
					})
			},
			back() {
				this.$router.push({
					path: "/fore/book/homebooklist",
				})
			},
			findAllBookByType() {
				this.$get("/api/public/book/findAll", {
						params: {
							start: 0,
							pageline: 6,
							typeid: this.book.type.id
						}
					})
					.then((resp) => {
						this.TypeBookList = resp.data.data.lst
					})
			},
			formatDate(value) {
				const dateObj = new Date(value)
				const year = dateObj.getFullYear()
				const month = dateObj.getMonth() + 1
				const day = dateObj.getDate()
				return `${year}-${month}-${day}`
			}
		},
		created() {
			this.getBook()
			this.getComment()
		}
	}
</script>

<style>
	#change2:hover {
		/* 鼠标移入时的样式 */
		color: orange;
	}

	#change3:hover {
		/* 鼠标移入时的样式 */
		color: red;
	}

	table tr td {}
</style>