<template>
	<div style="text-align: center;margin-top: 20px;">
		<i class="el-icon-notebook-2 " style="color: blueviolet;"></i>
		<span style="color: #3f7fce;font-weight: 600;">头像更新</span>
		<hr>
		<el-upload class="avatar-uploader" action="/api/public/upload" :show-file-list="false"
			:on-success="handleAvatarSuccess" :file-list="fileList" ref="uploadCompent">
			<img v-if="imageUrl" :src="imageUrl" class="avatar">
			<i v-else class="el-icon-plus avatar-uploader-icon"></i>
		</el-upload>
		<el-button type="danger" @click="beforeAvatarUpload">更新头像</el-button>
	</div>
</template>

<script>
	import {
		mapActions,
		mapState
	} from 'vuex'
	export default {
		data() {
			return {
				imageUrl: '',
				fileList:[]
			};
		},
		methods: {
			handleAvatarSuccess(res, file) {
				this.imageUrl = URL.createObjectURL(file.raw);
			},
			beforeAvatarUpload() {
				let files1 = this.$refs.uploadCompent.uploadFiles
				let that = this
				let fd = new FormData();
				console.log(this.user)
				fd.append("mypic", files1[0].raw);
				//将对象转换为json类型和文件一起提交到后端
				fd.append('img', this.user.img);
				this.$postf(
					"/api/userc/my/updateHead",
					fd
				).then(function(resp) {
					location.reload()
				}).catch(function(error) {
					console.log(error)
				})

			}
		},
		computed: {
			...mapState('user', ['user'])
		},
	}
</script>

<style>
	.avatar-uploader .el-upload {
		border: 1px dashed #d9d9d9;
		border-radius: 6px;
		cursor: pointer;
		position: relative;
		overflow: hidden;
	}

	.avatar-uploader .el-upload:hover {
		border-color: #409EFF;
	}

	.avatar-uploader-icon {
		font-size: 28px;
		color: #8c939d;
		width: 178px;
		height: 178px;
		line-height: 178px;
		text-align: center;
	}

	.avatar {
		width: 178px;
		height: 178px;
		display: block;
	}
</style>