<template>
	<div style="text-align: center;margin-top: 20px;">
		<i class="el-icon-notebook-2 " style="color: blueviolet;"></i>
		<span style="color: #3f7fce;font-weight: 600;">更改密码</span>
		<hr>
		<div style="display: flex;justify-content: center;align-items: center;">
			<el-form :model="ruleForm" label-position="left" label-width="100px" :rules="rules" ref="ruleForm">
				<el-form-item label="旧密码" prop="oldpass">
					<el-input type="password" size="small" v-model="ruleForm.old"></el-input>
				</el-form-item>
				<el-form-item label="新密码" prop="pass">
					<el-input type="password" size="small" v-model="ruleForm.pass" ></el-input>
				</el-form-item>
				<el-form-item label="新密码确认" prop="checkpass" style="width: 500px">
					<el-input type="password" size="small" v-model="ruleForm.checkPass" ></el-input>
				</el-form-item>
				<el-form-item>
					<el-button type="danger" @click="submitForm('ruleForm')">点击修改密码</el-button>
				</el-form-item>
			</el-form>
		</div>
	</div>
</template>

<script>
	export default {
		data() {
			var validateOld = (rule, value, callback) => {
				if (this.ruleForm.old === '') {
					callback(new Error('请输入旧密码'))
				} else {
					callback()
				}
			}
			var validatePass = (rule, value, callback) => {
				if (this.ruleForm.pass === '') {
					callback(new Error('请输入密码'))
				} else {
					if (this.ruleForm.checkPass !== '') {
						this.$refs.ruleForm.validateField('checkPass')
					}
					callback();
				}
			};
			var validatePass2 = (rule, value, callback) => {
				if (this.ruleForm.checkPass === '') {
					callback(new Error('请再次输入密码'))
				} else if (this.ruleForm.checkPass !== this.ruleForm.pass) {
					callback(new Error('两次输入密码不一致!'))
				} else {
					callback()
				}
			};
			return {
				ruleForm: {
					pass: '',
					checkPass: '',
					old: ''
				},
				rules: {
					oldpass: [{
						validator: validateOld,
						trigger: 'blur'
					}],
					pass: [{
						validator: validatePass,
						trigger: 'blur'
					}],
					checkpass: [{
						validator: validatePass2,
						trigger: 'blur'
					}],
				},
			};
		},
		methods: {
			submitForm(formName) {
				this.$refs[formName].validate((valid) => {
					if (valid) {
						this.$postx(`/api/userc/my/updatePwd/${this.ruleForm.old}/${this.ruleForm.pass}`)
							.then((resp) => {
								if(resp.data.code == 200){
								this.$message({
									type: 'success',
									message: resp.data.msg
								})
								}else{
									this.$message({
										type:"error",
										message: resp.data.msg
									})
								}
							}).catch(function(error) {
								console.log(error)
							})
					} else {
						console.log('error submit!!');
						return false;
					}
				})
			},
		},
		update() {

		},
		created() {

		}
	}
</script>

