<template>
	<div style="margin-left: 4px;width: 100%;">
		<div style="display: flex;">
			<div style="margin-top: 10px;height: 40px;background-color: #d9ecff;width: 50%;display: flex;align-items: center;">
				<p style="color: #409EFF;">商品一级类型</p>
			</div>
			<div style="margin-top: 10px;height: 40px;background-color: #d9ecff;width: 50%;display: flex;align-items: center;">
				<el-button type="primary" @click="goAdd()"><i class="el-icon-plus"></i>添加一层类型</el-button>
				<el-dialog title="类型信息" :visible.sync="dialogVisible" width="50%">
					<table style="width: 100%;">
						<tr>
							<td><span>一级ID:</span></td>
							<td><el-input type="text" style="width: 80%;" disabled v-model="nowType.id"></el-input></td>
						</tr>
						<tr>
							<td><span>一级类型名称:</span></td>
							<td><el-input type="text" style="width: 80%;" v-model="nowType.name"></el-input></td>
						</tr>
						<tr>
							<td><span>显示顺序:</span></td>
							<td><el-input type="text" style="width: 80%;" v-model="nowType.prio"></el-input></td>
						</tr>
					</table>
					<span slot="footer" class="dialog-footer">
						<el-button type="primary" @click="addType()" v-show="add == true">添加</el-button>
						<el-button type="primary" @click="updateType()" v-show="add == false">修改</el-button>
					</span>
				</el-dialog>

				<p style="margin-left: 10vw;color: #409EFF;">简单演示系统只需要一级类型即可</p>
			</div>
		</div>
		<el-table style="width: 100%;margin-top: 10px;" :data="types"
			:header-cell-style="{color: '#FFFFFF',background:'#AAAAAA'}">
			<el-table-column prop="id" label="一级类型id">
			</el-table-column>
			<el-table-column prop="prio" label="顺序">
			</el-table-column>
			<el-table-column prop="name" label="一级类型名称">
			</el-table-column>
			<el-table-column label="修改">
				<template slot-scope="scope">
					<el-button @click="goUpdate(scope.row)"><i class="el-icon-edit"></i></el-button>
				</template>
			</el-table-column>
			<el-table-column label="二级节点信息" width="300px">
				<template slot-scope="scope">
					<div class="parent">
						<div class="child" v-for="(i,index) in scope.row.children">
							{{i.name}}&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;
						</div>
					</div>
				</template>
			</el-table-column>
		</el-table>
	</div>
</template>

<script>
	export default {
		data() {
			return {
				types: [],
				children: [],
				data: [],
				dialogVisible: false,
				nowType: {
					id: 0
				},
				add: true
			};
		},
		computed: {

		},
		methods: {
			addType() {
				var that = this
				this.$postx(
					"/api/adm/type/add",
					this.nowType
				).then(function(resp) {
					that.nowType = {}
					that.types = []
					that.getTypeList()
					that.dialogVisible = false
				})
			},
			goAdd() {
				this.add = true
				this.nowType = {
					id: 0
				}
				this.dialogVisible = true
			},
			goUpdate(type) {
				this.add = false
				this.nowType = type
				this.dialogVisible = true
			},
			updateType() {
				var that = this
				this.$postx(
					"/api/adm/type/update",
					this.nowType
				).then(function(resp) {
					that.nowType = {}
					that.types = []
					that.getTypeList()
					that.dialogVisible = false
				})
			},
			getTypeList() {
				var that = this;
				this.$get("/api/public/type/findAll")
					.then((resp) => {
						console.log("获取后端类型数据， 不是树的结构，需要前端处理")
						this.data = resp.data.data
						console.log(this.data)
						console.log(this.data.length)
						for (let i = 0; i < this.data.length; i++) {
							if (this.data[i].pid === 0) {
								console.log(this.data[i])
								this.types.push(this.data[i]);
							}
						}
						console.log(this.types)
						for (let x = 0; x < this.types.length; x++) {
							for (let i = 0; i < this.data.length; i++) {
								if (this.data[i].pid == this.types[x].id) {
									this.children.push(this.data[i])
									this.types[x].children = this.children
								}
							}
							this.children = []
						}
						console.log("整理类型的结构， 形成树的结构")
						console.log(this.types)
						console.log("根据顺序进行排序")
						this.types.sort((a, b) => {
							return a.prio - b.prio
						})
						for (let i = 0; i < this.types.length; i++) {
							if (this.types[i].children != null) {
							this.types[i].children.sort((a, b) => {
								return a.prio - b.prio
							})
							}
						}
					})
			},
			},
		created() {
			this.getTypeList()
		}
	}
</script>

<style>
	.parent {
		display: flex;
		flex-wrap: wrap;
	}

	.child {
		width: 130px;
		white-space: nowrap;
	}
</style>