<template>
	<div>
		<div class="menuDiv">
			<div style="width: 1%;"></div>
			<el-avatar  style="margin-top: 15px;" :src="`https://cube.elemecdn.com/3/7c/3ea6beec64369c2642b92c6726f1epng.png`" v-if="user == null"></el-avatar>
			<el-avatar  style="margin-top: 15px;" size="large"  :src="`http://127.0.0.1/api/public/showimg/${user.img}`" v-if="user != null"></el-avatar>
			<div style="width: 5%;"></div>
			<el-link type="info" style="font-size: 17px;font-weight: 600;" :underline="false" @click="backHome()">当当网</el-link>
			<div style="width: 30%;"></div>
			<el-link style="font-size: 17px;font-weight: 600;" :underline="false" type="info">你好!</el-link>
			<el-link type="warning" v-if="user!=null"style="font-size: 17px;font-weight: 600;"
			 @click="goMyManager()" :underline="false">{{user.account}}&nbsp;</el-link>
			<el-link type="danger" @click="outUser1" style="font-size: 17px;font-weight: 600;"
			 :underline="false" v-show="user!=null">退出登录</el-link>
			<el-popover placement="top" width="300" v-model="visible" v-show="user==null">
				<div style="text-align: center;">
					<p style="color: dimgrey;font-weight:600;">用户登录</p>
					<hr>
					<el-input style="" type="text" v-model="user1.username"></el-input>
					<el-input type="password" style="margin-top: 5px;" v-model="user1.password"></el-input>
					<el-button type="primary" style="margin-top: 5px;width: 300px;" @click="login()">登录</el-button>
					<span style="color: skyblue;">忘记密码&nbsp;&nbsp;</span>
					<span style="color: skyblue;">用户注册</span>
				</div>
				<el-link type="danger" style="font-size: 17px;font-weight: 600;margin-top: 18.5px;" slot="reference"
				  :underline="false">请登录</el-link>
			</el-popover>


			<div style="width: 10%;"></div>
			<el-link type="primary" @click="goRegister()" :underline="false" style="font-size: 17px;font-weight: 600;">免费注册</el-link>
			<div style="width: 5%;"></div>
			<el-link type="primary" @click="goCart()" :underline="false"
				style="font-size: 17px;font-weight: 600;">|我的购物车|&nbsp;</el-link>
			<el-link type="primary"  @click="goOrderMsg()"
			:underline="false" style="font-size: 17px;font-weight: 600;"
			>|我的订单|</el-link>
		</div>
		<div>
			<router-view style="height: 90%;"></router-view>
		</div>
	</div>
</template>

<script>
	import {
		mapActions,
		mapState
	} from 'vuex'
	export default {
		data() {
			return {
				visible: false,
				user1: {},
			};
		},
		computed: {
			...mapState('user', ['user']),
		},
		methods: {
			...mapActions('user', ['selWord', 'outUser']),
			backHome() {
				this.$router.push("/fore/home/main")
			},
			goOrderMsg(){
				this.$router.push("/fore/ord/orderMessage")
			},
			goMyManager() {
				if (this.user.role == "usr") {
					this.$router.push({
						path: "/fore/user/center"
					})
				}
				if (this.user.role == "adm") {
					this.$router.push({
						path: "/adm/home"
					})
				}
			},
			goRegister(){
				this.$router.push({
					path: "/fore/home/register"
				})
			},
			goCart() {
				this.$router.push({
					path: "/fore/ord/myCart"
				})
			},
			login() {
				let that = this
				this.$postx("/api/login", this.user1).then(function(resp) {
					that.$message({
						type: 'success',
						message: "登录成功"
					})
					window.localStorage.setItem("token", resp.data.token);
					that.$get("/api/user/info").then(function(resp) {
						that.selWord({
							id: resp.data.data.id,
							account: resp.data.data.username,
							role: resp.data.data.role,
							img: resp.data.data.img,
						})
					})

				}).catch(function(error) {

				})
			},
			outUser1() {
				this.outUser()
				this.$router.push({
					path: "/fore/home/main"
				})
			},
		}
	}
</script>

<style>
	.menuDiv {
		width: 100%;
		height: 60px;
		margin-top: -20px;
		background: linear-gradient(gainsboro 10%, white, gainsboro 90%);
		display: flex;
	}

	

</style>