<template>
	<div style="text-align: center;margin-top: 20px;">
		<i class="el-icon-notebook-2 "
				style="color: blueviolet;"></i>
			<span style="color: #3f7fce;font-weight: 600;">修改个人信息</span>
			<hr>
			<div style="display: flex;justify-content: center;align-items: center;">
				<el-form :model="ruleForm" label-position="left" label-width="100px" :rules="rules" ref="ruleForm">
					<el-form-item label="昵称" prop="nickname">
						<el-input size="small" v-model="ruleForm.nickname"></el-input>
					</el-form-item>
					<el-form-item label="电话" prop="phone">
						<el-input  size="small" v-model="ruleForm.phone"></el-input>
					</el-form-item>
					<el-form-item label="地址" prop="addr" style="width: 500px">
						<el-input type="textarea"  v-model="ruleForm.addr"></el-input>
					</el-form-item>
					<el-form-item>
						<el-button type="danger" @click="submitForm('ruleForm')">点击修改</el-button>
					</el-form-item>
				</el-form>
			</div>
	</div>
</template>

<script>
	import {mapActions,mapState} from 'vuex'
	export default {
		data() {
			var validateNickname = (rule, value, callback) => {
				if (this.ruleForm.nickname === '') {
					callback(new Error('请输入昵称'))
				} else {
					callback()
				}
			}
			var validatePhone = (rule, value, callback) => {
				if (this.ruleForm.phone === '') {
					callback(new Error('请输入电话号码'))
				} else {
					callback()
				}
			}
			var validateAddr = (rule, value, callback) => {
				if (this.ruleForm.addr === '') {
					callback(new Error('请输入地址'))
				} else {
					callback()
				}
			}
			return {
				ruleForm: {
					
				},
				rules: {
					nickname: [{
						validator: validateNickname,
						trigger: 'blur'
					}],
					phone: [{
						validator: validatePhone,
						trigger: 'blur'
					}],
					addr: [{
						validator: validateAddr,
						trigger: 'blur'
					}],
				},
			};
		},
		computed: {
			...mapState('user', ['user'])
		},
		methods: {
			submitForm(formName) {
				this.$refs[formName].validate((valid) => {
					if (valid) {
						this.$postx(`/api/userc/my/updateMsg`,this.ruleForm)
							.then((resp) => {
								this.$message({
									type: 'success',
									message: resp.data.msg
								})
								}
							).catch(function(error) {
								console.log(error)
							})
					} else {
						console.log('error submit!!');
						return false;
					}
				})
			},
		},
		update() {
	
		},
		created() {
			this.$get("/api/userc/my/findOne",{
				params:{
					id:this.user.id
				}
			}).then((resp) => {
					console.log(resp.data.data)
					this.ruleForm = resp.data.data
				})
			
		}
	}
</script>

