<template>
	<div style="margin-left: 4px;width: 100%;">
		<div style="display: flex;">
			<div style="margin-top: 10px;height: 40px;background-color: #d9ecff;width: 50%;">
				<p style="line-height: 10px;color: #409EFF;">商品二级类型</p>
			</div>
			<div style="margin-top: 10px;height: 40px;background-color: #d9ecff;width: 50%;">
				<el-dialog title="类型信息" :visible.sync="dialogVisible" width="50%">
					<table style="width:35%;">
						<tr>
							<td>父节点id:</td>
							<td>{{fatherType.id}}</td>
						</tr>
						<tr>
							<td>父节点名称:</td>
							<td>{{fatherType.name}}</td>
						</tr>
					</table>
					<hr>
					<table style="width: 100%;">
						<tr>
							<td><span>二级类型名称:</span></td>
							<td><el-input type="text" style="width: 80%;" v-model="nowType.name"></el-input></td>
						</tr>
						<tr>
							<td><span>显示顺序:</span></td>
							<td><el-input type="text" style="width: 80%;" v-model="nowType.prio"></el-input></td>
						</tr>
					</table>
					<span slot="footer" class="dialog-footer">
						<el-button type="primary" @click="addType()" v-show="add == true">添加</el-button>
						<el-button type="primary" @click="updateType()" v-show="add == false">修改</el-button>
					</span>
				</el-dialog>
		
				<p style="float: right;line-height: 10px;color: #409EFF;">简单演示系统只需要一级类型即可</p>
			</div>
		</div>
		
		<el-table style="width: 100%;margin-top: 10px;"
		:data="types" 
		:header-cell-style="{color: '#FFFFFF',background:'#AAAAAA'}">
			<el-table-column prop="id" label="一级类型id">
			</el-table-column>
			<el-table-column prop="prio"  label="顺序">
			</el-table-column>
			<el-table-column  prop="name" label="一级类型名称">
			</el-table-column>
		
		
			<el-table-column label="二级节点信息" width="500px">
				<template slot-scope="scope">
					
					
					<div  v-for="(i,index) in scope.row.children" style="display: flex; align-items: center;">
					  <div  style="width: 80%;"><span>{{i.prio}}&nbsp;{{i.name}}&nbsp;</span></div>
					  <div style="width: 10%;"><el-link @click="goUpdate(i,scope.row)" icon="el-icon-edit" style="margin-left: 10%;color:chocolate "></el-link></div>
					  <div  style="width: 10%;"><el-link @click="remove(i)" icon="el-icon-close" style="margin-left: 10%;color: red;"></el-link></div>
					</div>
				</template>
			</el-table-column>
			<el-table-column   label="添加子类型">
				<template slot-scope="scope">
				<el-button @click="goAdd(scope.row)"><i class="el-icon-circle-plus-outline"></i></el-button>
				</template>
			</el-table-column>
		</el-table>
	</div>
</template>

<script>
	export default {
		data() {
			return {
				types: [],
				children: [],
				data: [],
				dialogVisible: false,
				nowType: {
					id:0
				},
				fatherType:{},
				add:true
			};
		},
		computed: {
	
		},
		methods: {
			addType() {
				var that = this
				this.nowType.pid = this.fatherType.id
				this.$postx(
					"/api/adm/type/add",
					this.nowType
				).then(function(resp) {
					that.nowType = {}
					that.types = []
					that.getTypeList()
					that.dialogVisible = false
				})
			},
			remove(i){
				var that = this
				this.$postx(
					"/api/adm/type/remove",
					i
				).then(function(resp) {
					that.types = []
					that.getTypeList()
				})
			},
			goAdd(father){
				this.fatherType = father
				this.add = true
				this.nowType = {id:0}
				this.dialogVisible = true
			},
			goUpdate(type,father){
				this.fatherType = father
				this.add = false
				this.nowType = type
				this.dialogVisible = true
			},
			updateType(){
				var that = this
				this.$postx(
					"/api/adm/type/update",
					this.nowType
				).then(function(resp) {
					that.nowType = {}
					that.types = []
					that.getTypeList()
					that.dialogVisible = false
				})
			},
			getTypeList() {
				var that = this;
				this.$get("/api/public/type/findAll")
					.then((resp) => {
						console.log("获取后端类型数据， 不是树的结构，需要前端处理")
						this.data = resp.data.data
						console.log(this.data)
						console.log(this.data.length)
						for (let i = 0; i < this.data.length; i++) {
							if (this.data[i].pid === 0) {
								console.log(this.data[i])
								this.types.push(this.data[i]);
							}
						}
						console.log(this.types)
						for (let x = 0; x < this.types.length; x++) {
							for (let i = 0; i < this.data.length; i++) {
								if (this.data[i].pid == this.types[x].id) {
									this.children.push(this.data[i])
									this.types[x].children = this.children
								}
							}
							this.children = []
						}
						console.log("整理类型的结构， 形成树的结构")
						console.log(this.types)
						console.log("根据顺序进行排序")
						this.types.sort((a, b) => {
							return a.prio - b.prio
						})
						for (let i = 0; i < this.types.length; i++) {
							if (this.types[i].children != null) {
							this.types[i].children.sort((a, b) => {
								return a.prio - b.prio
							})
							}
						}
					})
			},
			},
		created() {
			this.getTypeList()
		}
	}
</script>

