<template>
	<div>
		<div>
			<div style="text-align: center;margin-top: 15px;"><i class="el-icon-s-order "
					style="color: blueviolet;"></i>
					<span style="color: #adc1c4;font-weight: 600;" 
					v-show="order == false">下单-待从购物车转订单</span>
					<span style="color: #adc1c4;font-weight: 600;"
					v-show="order == true">下单-待付款</span>
					</div>
			<hr>

			<el-table style="width: 90%;margin-top: 10px;margin-left: 5%;" :data="checkCart" border>
				<el-table-column label="图片">
					<template slot-scope="scope">
						<img :src="'http://127.0.0.1:80/api/public/showimg/'+scope.row.book.pic"
							style="width: 70px;height: 70px;">
					</template>
				</el-table-column>
				<el-table-column prop="book.name" label="商品名称">
				</el-table-column>
				<el-table-column prop="book.price" label="商品价钱">
				</el-table-column>
				<el-table-column label="商品数量" width="200">
					<template slot-scope="scope">
						<el-input type="number" v-model="scope.row.num"  :min="1"></el-input>
					</template>
				</el-table-column>
				<el-table-column label="商品总价">
					<template slot-scope="scope">
						<p>{{scope.row.num*scope.row.book.price}}</p>
					</template>
				</el-table-column>
			</el-table>
			<div style="height: 25px;background-color:gainsboro;width: 90%;margin-left: 5%;">
				<span style="font-weight: 600;" v-show="order == false">请确认完善收货人信息</span>
				<span style="font-weight: 600;color: red" v-show="order == true">请确认订单号:{{ordid}}</span>
			</div>
			<div style="height: 100px;width: 90%;margin-left: 5%;border: 1px solid skyblue;text-align: center;">
				<div><span>姓名</span><el-input style="width: 60%;" size="mini" v-model="userA.nickname"></el-input></div>
				<div  style="margin-top: 5px;"><span>电话</span><el-input style="width: 60%;" size="mini" v-model="userA.phone"></el-input></div>
				<div style="margin-top: 5px;"><span>地址</span><el-input style="width: 60%;" size="mini" v-model="userA.addr"></el-input></div>
			</div>
			<div style="height: 14px;background-color:gainsboro;width: 90%;margin-left: 5%;"></div>
			<div style="height: 50px;width: 90%;margin-left: 5%;">
				<div style="width: 25%;height: 50px;margin-left: auto;display: flex;">
					<p style="white-space: nowrap;">总价:&nbsp;&nbsp;&nbsp;</p>
					<p>{{totalPrice}}￥</p>
					<el-button @click="goOrder()" v-show="order == false"
					style="background-color: lightcoral;color: white;margin-left: auto;">下单</el-button>
					<el-button @click="goPay(ordid)" v-show="order == true"
					style="background-color: lightcoral;color: white;margin-left: auto;">去付款</el-button>
				</div>
			</div>
			<div style="height: 14px;background-color:gainsboro;width: 90%;margin-left: 5%;"></div>
		</div>
	</div>
</template>

<script>
	 import {
	 	mapActions,
	 	mapState
	 } from 'vuex'
	export default {
		data() {
			return {
				checkCart: this.$route.params.checkCart,
				totalPrice: 0,
				userA:{},
				ordid:0,
				order:false,
				cart2Ord:{}
			};
		},
		computed: {
			 ...mapState('user', ['user']),
		},
		methods: {
			goOrder(){
				var that = this
				if(this.checkCart != null){
					this.cart2Ord.carts =this.checkCart
					this.cart2Ord.ship2name = this.userA.nickname
					this.cart2Ord.ship2phone = this.userA.phone
					this.cart2Ord.ship2addr = this.userA.addr
				for(let i=0;i<this.checkCart.length;i++){
					this.$get("/api/userc/cart/remove",{params:{id:this.checkCart[i].id}})
				}
				console.log(this.cart2Ord)
				var jsonData = JSON.stringify(this.cart2Ord);
				this.$postj("/api/userc/order/createOrder",jsonData)
				.then(function(resp) {
					that.ordid = resp.data.data
					that.$message({
						type: 'success',
						message: `订单下单成功,订单号:${that.ordid}`
					})
					that.order = true
				})
				}
			},
			goPay(ordid){
				this.$router.push({
					path:"/fore/ord/payMoney",
					query:{ordid:ordid}
				})
			}
			
		},
		created() {
			this.$get("/api/userc/my/findOne",{
				params:{
					id:this.user.id
				}
			}).then((resp) => {
					this.userA = resp.data.data
				})
				if(this.checkCart != null){
			for (let i = 0; i < this.checkCart.length; i++) {
				this.totalPrice += this.checkCart[i].num * this.checkCart[i].book.price
			}
			}
			
		}
	}
</script>

<style>
	hr {
		width: 90%;
		border: 1px solid skyblue;
	}
</style>