<template>
	<div>
		<div style=" display: flex; justify-content: space-around;">
			<div><img src="../../../assets/105742_300.png"        style="width: 15vw; height: 15vh;"></div>
			<div style="margin-top: 60px;"><el-input placeholder="请输入内容" v-model="key" style="width: 300px;"></el-input><el-button
					type="danger" icon="el-icon-search" @click="doSearch()">搜索</el-button></div>
			<div><el-button type="danger" icon="el-icon-shopping-cart-2" style="margin-top: 60px;">我的购物车</el-button>
			</div>
		</div>
		
		<hr>
		<div style="display: flex;margin-left: 100px;">
			<!-- 类型侧边菜单 -->
			<div style="width: 25%;">
				<div id="change1" @click="showTypeBookList1(0)" >
					<span v-if="typeid == 0 && search == false" style="fontWeight:bold;">全部类型:默认</span>
					<span v-else>全部类型:默认</span>
					<span style="color:  #f8987a;float: right;"><i class="el-icon-arrow-right"></i></span>
				</div>
				<div v-for="i in types">
					<div id="change1" @click="showTypeBookList1(i.id)" 
						style="margin-top: 10px;overflow: hidden;white-space: nowrap;text-overflow: ellipsis;">
						<span v-if="typeid == i.id && search == false" style="fontWeight:bold;">{{i.name}}</span>
						<span v-else>{{i.name}}</span>
						<span style="color:  #f8987a;float: right;"><i class="el-icon-arrow-right"></i></span>
					</div>
					<div id="change1" v-for="x in i.children"  @click="showTypeBookList1(x.id)"
					style="margin-top: 10px;overflow: hidden;white-space: nowrap;text-overflow: ellipsis;">
						<span  v-if="typeid == x.id && search == false" style="fontWeight:bold;">{{i.name}}/{{x.name}}</span>
						<span v-else>{{i.name}}/{{x.name}}</span>
						<span style="color: #f8987a;float: right;"><i class="el-icon-arrow-right"></i></span>
					</div>
				</div>
			</div>
			<!-- 类型侧边菜单 -->

			<!-- 图书列表-->
			<div style="width: 75%;">
			<el-table :data="books" style="margin-left: 50px;width: 1000px;" :show-header="false">
				<el-table-column width="auto">
					<template slot-scope="scope">	
					<div>
						<div  style="display: flex;width: 100%;">
							<div style="width: 10vw;height: 10vw;">
							<img :src="'http://127.0.0.1:80/api/public/showimg/'+scope.row.pic" style="width: 100%;height: 100%;">
							</div>
							<div style="width: 25vw;" id="yourContainerId">
								<!-- 第一行 -->
									<div style="height: 3vh;">
										<p style="font-weight: 600;overflow: hidden;white-space: nowrap;" v-html="scope.row.name"> {{scope.row.name}}</p>
									</div>
									<!-- 第二行 -->
									<div style="height: 3vh;display: flex;">
										<div style="width:5vw;">
										<span style="font-weight: 600;overflow: hidden;white-space: nowrap;"> {{scope.row.author}}</span>
										</div>
										<div>
										<span style="font-weight: 600;overflow: hidden;white-space: nowrap;"> {{scope.row.maker}}</span>
										</div>
									</div>
									<div style="height: 10vh;display: flex;">
										<span style="font-weight: 200;font-size: 10px;overflow: hidden;" v-html="scope.row.info"> {{scope.row.info}}</span>
									</div>
							</div>
							<div style="width: 20vw;margin-left: 5vw;">
								<!-- 第一行 -->
									<div>
										<el-button type="primary" size="mini" @click="goBookMessage(scope.row)"><i class="el-icon-chat-dot-square"></i>详情</el-button>
									</div>
									<div style="height: 3vh;">
										<span style="color: red;">￥{{scope.row.price}}</span>
									</div>
									<div>
										<el-button type="danger" size="mini" @click="buyBook(scope.row.id)"><i class="el-icon-shopping-cart-1"></i>购买</el-button>
									</div>
							</div>
						</div>
					</div>
					</template>
				</el-table-column>
			</el-table>
			<!-- 图书列表-->
			</div>
		</div>
		<div style="text-align: center;width: 100%;">
		<el-pagination  background layout="prev, pager, next" :hide-on-single-page="true" @current-change='current'
			:page-size="pageline" :total="total" :current-page="start">
		</el-pagination>
		</div>
	</div>
</template>

<script>
	import {
		mapActions,
		mapState
	} from 'vuex'
	export default {
		data() {
			return {
				data: [],
				children: [],
				types: [],
				books: [],
				typeid: 0,
				start: 1,
				total: 0,
				pageline: 6,
				typeid:this.$route.query.typeid,
				isBold:false,
				search:false,
				key:this.$route.query.key
			};
		},
		computed: {
			...mapState('user', ['user']),
		},
		components: {
		},
		methods: {
			buyBook(bookid){
				var that = this
				if(this.user == null){
					this.$message({
						type: 'error',
						message: "未登录,请先登录"
					})
				}else{
				this.$get(
					`/api/public/cart/addCart/${bookid}/${this.user.id}`
				).then(function(resp) {
					if(resp.data.code == 200){
					that.$message({
						type: 'success',
						message: resp.data.msg
					})
					}else{
						that.$message({
							type: 'error',
							message: resp.data.msg
						})
					}
				}).catch(function(error) {
					
				})
				}
			},
			current(i) {
				this.start = i
				if(this.search == false){
				this.showTypeBookList()
				}
				if(this.search == true){
					this.doSearch()
				}
				},
				goBookMessage(book){
					this.$router.push({
						name:"bookmessage",
						query:{bookid:book.id}
					})
				},
			getTypeList() {
				this.search = false
				var that = this;
				this.$get("/api/public/type/findAll")
					.then((resp) => {
						this.data = resp.data.data
						for (let i = 0; i < this.data.length; i++) {
							if (this.data[i].pid === 0) {
								this.types.push(this.data[i]);
							}
						}
					
						for (let x = 0; x < this.types.length; x++) {
							for (let i = 0; i < this.data.length; i++) {
								if (this.data[i].pid == this.types[x].id) {
									this.children.push(this.data[i])
									this.types[x].children = this.children
								}
							}
							this.children = []
						}
						this.types.sort((a, b) => {
							return a.prio - b.prio
						})
						for (let i = 0; i < this.types.length; i++) {
							if (this.types[i].children != null) {
								this.types[i].children.sort((a, b) => {
									return a.prio - b.prio
								})
							}
						}

					})
			},
			showTypeBookList1(typeid){
				this.search = false
				this.start = 1
				this.typeid = typeid
				this.showTypeBookList()
			},
			showTypeBookList() {
				this.search = false
				var that = this;
				this.$get("/api/public/book/findAll", {
						params: {
							start: (this.start - 1) * this.pageline,
							pageline: this.pageline,
							typeid: this.typeid
						}
					})
					.then((resp) => {
						this.books = resp.data.data.lst
							this.total = resp.data.data.count

					})
			},
			doSearch(){
				this.search = true
				this.$get("/api/public/book/findAllByKey", {
						params: {
							start: (this.start - 1) * this.pageline,
							pageline: this.pageline,
							key: this.key
						}
					})
					.then((resp) => {
						this.books = resp.data.data.lst
						this.total = resp.data.data.count
				})
			}
		},
		created() {
			this.getTypeList()
			if(this.key != null){
				this.doSearch()
				return
			}
			if(this.typeid == null){
				this.typeid =0
			}
			this.showTypeBookList()
			
			
		}
	}
</script>

<style>
	hr {
		width: 90%;
		border: 1px solid red;
	}

	#change1:hover {
		/* 鼠标移入时的样式 */
		border: 1px solid indianred;
		color: indianred;
	}
	.table-container .el-table__header-wrapper {
	  display: none;
	}
</style>