</template>

<script>
	import {
		mapActions,
		mapState
	} from 'vuex'
	export default {
		data() {
			return {
				data: [],
				children: [],
				types: [],
				hotimgs: [],
				books: [],
				key:""
			};
		},
		computed: {
			...mapState('user', ['user']),
		},
		components: {
		},
		methods: {
			buyBook(bookid){
				var that = this
				if(this.user == null){
					this.$message({
						type: 'error',
						message: "未登录,请先登录"
					})
				}else{
				this.$get(
					`/api/public/cart/addCart/${bookid}/${this.user.id}`
				).then(function(resp) {
					if(resp.data.code == 200){
					that.$message({
						type: 'success',
						message: resp.data.msg
					})
					}else{
						that.$message({
							type: 'error',
							message: resp.data.msg
						})
					}
				}).catch(function(error) {
					
				})
				}
			},
			getTypeList() {
				var that = this;
				this.$get("/api/public/type/findAll")
					.then((resp) => {
						this.data = resp.data.data
						for (let i = 0; i < this.data.length; i++) {
							if (this.data[i].pid === 0) {
								this.types.push(this.data[i]);
							}
						}
						for (let x = 0; x < this.types.length; x++) {
							for (let i = 0; i < this.data.length; i++) {
								if (this.data[i].pid == this.types[x].id) {
									this.children.push(this.data[i])
									this.types[x].children = this.children
								}
							}
							this.children = []
						}
						this.types.sort((a, b) => {
							return a.prio - b.prio
						})
						for (let i = 0; i < this.types.length; i++) {
							if (this.types[i].children != null) {
							this.types[i].children.sort((a, b) => {
								return a.prio - b.prio
							})
							}
						}

					})
			},
			goBookList(typeid){
				this.$router.push({
					path:'/fore/book/homebooklist',
					query:{typeid:typeid}
				})
			},
			doSearch(){
				this.$router.push({
					path:"/fore/book/homebooklist",
					query:{key:this.key}})
			},
			goCart() {
				this.$router.push({
					path: "/fore/ord/myCart"
				})
			},
			},
		created() {
			this.getTypeList()
			var that = this;
			this.$get("/api/public/hot/findAll")
				.then((resp) => {
					this.hotimgs = resp.data.data
				})
			this.$get("/api/public/book/findAll", {
					params: {
						start: 0,
						pageline: 10,
						typeid:0
					}
				})
				.then((resp) => {
					this.books = resp.data.data.lst
				})
		}
	}
</script>

