<template>
	<div style="margin-left: 4px;width: 100%;text-align: center;">
		<div style="display: flex;">
			<div style="margin-top: 10px;">
				<p style="margin-top: 11px;float: left;white-space: nowrap;"><i class="el-icon-s-data"></i>后台订单管理</p>
			</div>
			<div style="margin-top: 10px;margin-left: 10%;">
				<div>
					<el-select style="width: 90%;" v-model="payStatus" placeholder="付款" size="small">
						<el-option label="-请选择-" :value="null">
						</el-option>
						<el-option label="未付款" :value="0">
						</el-option>
						<el-option label="已付款" :value="1">
						</el-option>
					</el-select>
				</div>
				<div>
					<el-input style="width: 90%;" size="small" placeholder="下单人-账号" v-model="account"></el-input>
				</div>
			</div>
			<div style="margin-top: 10px;">
				<div>
					<el-select style="width: 90%;" v-model="shipStatus" placeholder="发货" size="small">
						<el-option label="-请选择-" :value="null">
						</el-option>
						<el-option label="未发货" :value="0">
						</el-option>
						<el-option label="已发货" :value="1">
						</el-option>
						<el-option label="已收货" :value="2">
						</el-option>
					</el-select>
				</div>
				<div>
					<el-input style="width: 90%;" size="small" placeholder="下单人-手机号" v-model="phone"></el-input>
				</div>
			</div>
			<div style="margin-top: 10px;">
				<div>
					<el-select style="width: 90%;" v-model="days" placeholder="日期" size="small">
						<el-option label="-请选择-" :value="null">
						</el-option>
						<el-option label="7天内" :value="7">
						</el-option>
						<el-option label="15天内付款" :value="15">
						</el-option>
						<el-option label="30天内付款" :value="30">
						</el-option>
						<el-option label="60天内付款" :value="60">
						</el-option>
						<el-option label="120天内付款" :value="120">
						</el-option>
					</el-select>
				</div>
				<div>
					<el-input style="width: 90%;" size="small" placeholder="下单人-姓名" v-model="nickname"></el-input>
				</div>
			</div>
			<div style="margin-top: 10px;margin-left: 5%;">
				<div>
					<el-button type="primary" @click="doSearch()"><i class="el-icon-search"></i>查询</el-button>
				</div>

			</div>
		</div>
		<hr>
		<el-table style="width: 90%;margin-top: 10px;margin-left: 5%;" :data="orderList" border ref="table">
			<el-table-column type="expand">
				<template slot-scope="scope">
					<table style="margin: auto;">
						<tr>
							<td></td>
							<td> <span
									style="font-weight: 600;">&nbsp;&nbsp;&nbsp;账号:</span>{{scope.row.user.account}}&nbsp;&nbsp;&nbsp;
							</td>
							<td> <span style="font-weight: 600;">电话:</span>{{scope.row.user.phone}}&nbsp;&nbsp;&nbsp;
							</td>
							<td><span style="font-weight: 600;"> 下单人:</span>{{scope.row.user.nickname}}</td>
						</tr>
						<tr v-for="i in scope.row.orderItem">
							<td> <img :src="'http://127.0.0.1:80/api/public/showimg/'+i.book.pic"
									style="width: 70px;height:70px;"></td>
							<td> <span
									style="font-weight: 600;">&nbsp;&nbsp;&nbsp;图书名称:</span>{{i.book.name}}&nbsp;&nbsp;&nbsp;
							</td>
							<td> <span style="font-weight: 600;">数量:</span>{{i.num}}&nbsp;&nbsp;&nbsp;</td>
							<td><span style="font-weight: 600;"> 单价:</span>￥{{i.price}}</td>
						</tr>
						<tr>
							<td>
								<el-popover placement="top" width="300">
									<div style="text-align: center;">
										<p style="color: dimgrey;font-weight:600;">请输入发货信息</p>
										<hr>
										<el-form :rules="rules">
											<el-form-item label="发货单号" prop="shipno">
												<el-input v-model="shipno"></el-input>
											</el-form-item>
											<el-form-item label="快递公司或快递员" prop="shipper">
												<el-input v-model="shipper"></el-input>
											</el-form-item>
											<el-form-item>
												<el-button type="primary" style="width: 100%;"
													@click="updateShip(scope.row.ordid)">确认发货</el-button>
											</el-form-item>
										</el-form>
									</div>
									<el-button style="margin: auto;" slot="reference"
										v-show="scope.row.ship_status == 0 && scope.row.pay_status == 1" type="warning"
										@click="getShippno(scope.row.ordid)">发货</el-button>
								</el-popover>
							</td>
						</tr>
					</table>
				</template>
			</el-table-column>
			<el-table-column prop="ordid" label="订单号">
			</el-table-column>
			<el-table-column prop="user.nickname" label="收货人">
			</el-table-column>
			<el-table-column prop="user.addr" label="收货地址">
			</el-table-column>
			<el-table-column prop="user.phone" label="电话">
			</el-table-column>
			<el-table-column prop="shipno" label="发货单号">
			</el-table-column>
			<el-table-column prop="tcreate" label="下单时间">
			</el-table-column>
			<el-table-column prop="amount" label="总价">
			</el-table-column>
			<el-table-column label="付款">
				<template slot-scope="scope">
					<el-link v-show="scope.row.pay_status == 0" style="font-weight: 600;color: purple;">未付</el-link>
					<span v-show="scope.row.pay_status == 1" style="font-weight: 600;color: gray;">已付</span>
				</template>
			</el-table-column>
			<el-table-column label="收货">
				<template slot-scope="scope">
					<span v-show="scope.row.ship_status == 0 && scope.row.pay_status == 0"
						style="font-weight: 600;">待发</span>
					<el-link v-show="scope.row.ship_status == 0 && scope.row.pay_status == 1"
						@click="toggleRowExpansion(scope.row,scope.row.expanded)" style="font-weight: 600;color: red;"
						:underline="false">可发</el-link>
					<span v-show="scope.row.ship_status == 1" style="font-weight: 600;color: orange;">已发</span>
					<span v-show="scope.row.ship_status == 2" style="font-weight: 600;color: gray;">已收</span>
				</template>
			</el-table-column>
		</el-table>
		<div style="text-align: center;">
			<el-pagination background layout="prev, pager, next" :hide-on-single-page="true" @current-change='current'
				:page-size="pageline" :total="total">
			</el-pagination>
		</div>
	</div>
</template>

<script>
	export default {
		data() {
			return {
				start: 1,
				total: 0,
				pageline: 6,
				payStatus: '',
				shipStatus: '',
				days: '',
				account: '',
				phone: '',
				nickname: '',
				shipno: '',
				shipper: '',
				orderList: [],
				rules: {
					shipno: [{
						required: true,
						message: '请输入',
						trigger: 'blur'
					}, ],
					shipper: [{
						required: true,
						message: '请输入',
						trigger: 'blur'
					}, ],

				},
			};
		},
		computed: {

		},
		methods: {
			current(i) {
				this.start = i
				this.getOrderList()
			},
			doSearch() {
				this.$get("/api/adm/order/findAllAdm", {
						params: {
							payStatus: this.payStatus,
							shipStatus: this.shipStatus,
							days: this.days,
							account: this.account,
							phone: this.phone,
							nickname: this.nickname,
							start: (this.start - 1) * this.pageline,
							pageline: this.pageline
						},
					})
					.then((resp) => {
						this.orderList = resp.data.data.lst
						this.total = resp.data.data.count
					})
			},
			getOrderList() {
				this.$get("/api/adm/order/findAllAdm", {
						params: {
							start: (this.start - 1) * this.pageline,
							pageline: this.pageline
						}
					})
					.then((resp) => {
						this.orderList = resp.data.data.lst
						this.total = resp.data.data.count
					})
			},
			getShippno(ordid) {
				let date = new Date();
				this.shipno = date.getFullYear() + `${(date.getMonth()+1)}` + `${date.getDate()}` + `${ordid}`
			},
			toggleRowExpansion(row, expanded) {
				this.$refs.table.toggleRowExpansion(row, expanded);
				// toggleRowExpansion用于展开收起子行,是el-table组件的一个方法
				// row表示要展开或收起的行的数据对象，expanded表示是否展开行
			},
			updateShip(ordid) {
				if (this.shipper != null &&
					this.shipper != '' &&
					this.shipno != null &&
					this.shipno != '') {
					let fd = new FormData();
					fd.append("shipno", this.shipno)
					fd.append("shipper", this.shipper)
					this.$postj(`/api/adm/order/updateShip/${ordid}`, fd

						)
						.then((resp) => {
							this.$alert(`订单${ordid}发货成功,请注意查看`, {
								confirmButtonText: '确定',
								callback: action => {
									this.$message({
										type: 'success',
										message: `订单${ordid}发货成功`
									});
								}
							})
							this.getOrderList()
						})
				}
			},
		},
		created() {
			this.getOrderList()
		}
	}
</script>

<style>
	hr {
		width: 100%;
		border: 1px solid skyblue;
	}
</style>