<template>
	<div>
		<div>
			<div style="text-align: center;margin-top: 15px;"><i class="el-icon-notebook-2 "
					style="color: blueviolet;"></i>
				<span style="color: #3f7fce;font-weight: 600;">我的订单详情</span>
				<el-select style="margin-left: 30%;width: 10%;" v-model="payStatus" placeholder="付款" size="small">
					<el-option label="-请选择-" :value="null">
					</el-option>
					<el-option label="未付款" :value="0">
					</el-option>
					<el-option label="已付款" :value="1">
					</el-option>
				</el-select>
				<el-select style="margin-left: 5px;width: 10%;" v-model="shipStatus" placeholder="发货" size="small">
					<el-option label="-请选择-" :value="null">
					</el-option>
					<el-option label="未发货" :value="0">
					</el-option>
					<el-option label="已发货" :value="1">
					</el-option>
					<el-option label="已收货" :value="2">
					</el-option>
				</el-select>
				<el-select style="margin-left: 5px;width: 10%;" v-model="days" placeholder="日期" size="small">
					<el-option label="-请选择-" :value="null">
					</el-option>
					<el-option label="7天内" :value="7">
					</el-option>
					<el-option label="15天内付款" :value="15">
					</el-option>
					<el-option label="30天内付款" :value="30">
					</el-option>
					<el-option label="60天内付款" :value="60">
					</el-option>
					<el-option label="120天内付款" :value="120">
					</el-option>
				</el-select>
				<el-button type="primary" style="margin-left: 10px;" size="small" @click="doSearch()"><i
						class="el-icon-search"></i>查询</el-button>
			</div>
			<hr>
			<el-dialog
			  title="收货确认"
			  :visible.sync="dialogVisible"
			  width="30%">
			  <span>确认已经收到货了吗?(确认后将不可撤回)</span>
			  <span slot="footer" class="dialog-footer">
			    <el-button @click="dialogVisible = false">取 消</el-button>
			    <el-button type="primary" @click="doSign()">确 定</el-button>
			  </span>
			</el-dialog>
			<el-table style="width: 90%;margin-top: 10px;margin-left: 5%;" :data="orderList" border>
				<el-table-column type="expand">
					<template slot-scope="scope">
						<table style="margin: auto;">
							<tr v-show="scope.row.ship_status == 1">
								<td> <span
										style="font-weight: 600;">&nbsp;&nbsp;&nbsp;承运人:</span>{{scope.row.shipper}}&nbsp;&nbsp;&nbsp;
								</td>
								<td><span
										style="font-weight: 600;">&nbsp;&nbsp;&nbsp;发货单号:</span>{{scope.row.shipno}}&nbsp;&nbsp;&nbsp;
								</td>
							</tr>
							<tr v-for="i in scope.row.orderItem">
								<td> <img :src="'http://127.0.0.1:80/api/public/showimg/'+i.book.pic"
										style="width: 70px;height:70px;"></td>
								<td> <span
										style="font-weight: 600;">&nbsp;&nbsp;&nbsp;图书名称:</span>{{i.book.name}}&nbsp;&nbsp;&nbsp;
								</td>
								<td> <span style="font-weight: 600;">数量:</span>{{i.num}}&nbsp;&nbsp;&nbsp;</td>
								<td><span style="font-weight: 600;"> 单价:</span>￥{{i.price}}</td>
							</tr>
						</table>
					</template>
				</el-table-column>
				<el-table-column prop="ordid" label="订单号">
				</el-table-column>
				<el-table-column prop="ship2name" label="收货人">
				</el-table-column>
				<el-table-column prop="ship2addr" label="收货地址">
				</el-table-column>
				<el-table-column prop="ship2phone" label="电话">
				</el-table-column>
				<el-table-column prop="shipno" label="发货单号">
				</el-table-column>
				<el-table-column label="下单时间">
					<template slot-scope="scope">
						<p>{{formatDate(scope.row.tcreate)}}</p>
					</template>
				</el-table-column>
				<el-table-column prop="amount" label="总价">
				</el-table-column>
				<el-table-column label="付款">
					<template slot-scope="scope">
						<el-link v-show="scope.row.pay_status == 0" @click="goPay(scope.row.ordid)" :underline="false"
							style="font-weight: 600;color: purple;">未付</el-link>
						<span v-show="scope.row.pay_status == 1" style="font-weight: 600;color: gray;">已付</span>
					</template>
				</el-table-column>
				<el-table-column label="收货">
					<template slot-scope="scope">
						<span v-show="scope.row.ship_status == 0" style="font-weight: 600;color: orange;">未发</span>
						<el-link @click="goSign(scope.row.ordid)" v-show="scope.row.ship_status == 1" 
						style="font-weight: 600;color: purple;":underline="false" >待收</el-link>
						<span v-show="scope.row.ship_status == 2" style="font-weight: 600;color: gray;">已收</span>
					</template>
				</el-table-column>
			</el-table>
			<div style="text-align: center;">
				<el-pagination background layout="prev, pager, next" :hide-on-single-page="true"
					@current-change='current' :page-size="pageline" :total="total" :current-page="start">
				</el-pagination>
			</div>
		</div>

	</div>

</template>

<script>
	export default {
		data() {
			return {
				dialogVisible:false,
				start: 1,
				total: 0,
				pageline: 6,
				orderList: [],
				payStatus: '',
				shipStatus: '',
				days: '',
				signOrdid:0
			};
		},
		methods: {
			goSign(ordid){
				this.signOrdid = ordid
				this.dialogVisible = true
			},
			doSign(){
				this.$postx(`/api/userc/order/doSign/${this.signOrdid}`)
					.then((resp) => {
						this.dialogVisible = false
						this.getSearchList()
						this.$message(
						{
							type:'success',
							message:'收货成功'
						})
					})
			},
			current(i) {
				this.start = i
				this.getSearchList()
			},
			doSearch() {
				this.start = 1
				this.getSearchList()
			},
			getSearchList() {
				this.$get("/api/userc/order/findAll", {
						params: {
							payStatus: this.payStatus,
							shipStatus: this.shipStatus,
							days: this.days,
							start: (this.start - 1) * this.pageline,
							pageline: this.pageline
						},
					})
					.then((resp) => {
						this.orderList = resp.data.data.lst
						this.total = resp.data.data.count
					})
			},
			formatDate(value) {
				const dateObj = new Date(value)
				const year = dateObj.getFullYear()
				const month = dateObj.getMonth() + 1
				const day = dateObj.getDate()
				return `${year}-${month}-${day}`
			},
			goPay(ordid) {
				this.$router.push({
					path: "/fore/ord/payMoney",
					query: {
						ordid: ordid
					}
				})
			}
		},
		created() {
			this.getSearchList()
		}
	}
</script>

