<template>
	<div style="text-align: center;margin-top: 20px;">
		<i class="el-icon-notebook-2 " style="color: blueviolet;"></i>
		<span style="color: #3f7fce;font-weight: 600;">用户注册</span>
		<hr style="width: 80%;">
		<div style="display: flex; ">
			<div style="width: 50%;">
				
					<el-upload class="avatar-uploader" action="/api/public/upload" :show-file-list="false"
						:on-success="handleAvatarSuccess" :file-list="fileList" ref="uploadCompent">
						<img v-if="imageUrl" :src="imageUrl" class="avatar">
						<i v-else class="el-icon-plus avatar-uploader-icon"></i>
					</el-upload>
			</div>
			<div style="width: 50%;">
				<el-form :model="user"  ref="user"  :rules="rules" label-width="100px" class="demo-ruleForm">
					<el-form-item label="账号:" prop="account">
						<el-input style="width: 100%;" size="small" v-model="user.account"></el-input>
					</el-form-item>
					<el-form-item label="密码:" prop="pass">
						<el-input type="password" style="width: 100%;" size="small" v-model="user.password"></el-input>
					</el-form-item>
					<el-form-item label="密码确认:" prop="checkPass">
						<el-input type="password" style="width: 100%;" v-model="user.checkPass"></el-input>
					</el-form-item>
					<el-form-item label="昵称:" prop="nickname">
						<el-input style="width: 100%;" v-model="user.nickname"></el-input>
					</el-form-item>
					<el-form-item label="手机号:" prop="phone">
						<el-input style="width: 100%;" v-model="user.phone"></el-input>
					</el-form-item>
					<el-form-item label="地址:" prop="addr">
						<el-input style="width: 100%;" :autosize="{ minRows: 2, maxRows: 8}" type="textarea"
							v-model="user.addr"></el-input>
					</el-form-item>
					<el-form-item>
						<el-button type="primary" @click="submitForm('user')">注册</el-button>
					</el-form-item>
				</el-form>
			</div>
		</div>
	</div>
</template>

<script>
	import {
		mapActions,
		mapState
	} from 'vuex'
	export default {
		data() {
			var validatePass = (rule, value, callback) => {
				if (this.user.password === '') {
					callback(new Error('请输入密码'))
				} else {
					if (this.user.checkPass !== '') {
						this.$refs.user.validateField('checkPass')
					}
					callback();
				}
			};
			var validatePass2 = (rule, value, callback) => {
				if (this.user.checkPass === '') {
					callback(new Error('请再次输入密码'))
				} else if (this.user.checkPass !== this.user.password) {
					callback(new Error('两次输入密码不一致!'))
				} else {
					callback()
				}
			};
			var validateNickname = (rule, value, callback) => {
				if (this.user.nickname === '') {
					callback(new Error('请输入昵称'))
				} else {
					callback()
				}
			}
			var validatePhone = (rule, value, callback) => {
				if (this.user.phone === '') {
					callback(new Error('请输入电话号码'))
				} else {
					callback()
				}
			}
			var validateAccount = (rule, value, callback) => {
				if (this.user.account === '') {
					callback(new Error('请输入账号'))
				} else {
					callback()
				}
			}
			var validateAddr = (rule, value, callback) => {
				if (this.user.addr === '') {
					callback(new Error('请输入地址'))
				} else {
					callback()
				}
			}
			return {
				imageUrl: '',
				fileList: [],
				user:{password: '',
					checkPass: '',
					account:'',
					phone:'',
					addr:'',
					nickname:''},
				rules: {
					pass: [{
						validator: validatePass,
						trigger: 'blur'
					}],
					checkPass: [{
						validator: validatePass2,
						trigger: 'blur'
					}],
					nickname: [{
						validator: validateNickname,
						trigger: 'blur'
					}],
					phone: [{
						validator: validatePhone,
						trigger: 'blur'
					}],
					addr: [{
						validator: validateAddr,
						trigger: 'blur'
					}],
					account: [{
						validator: validateAccount,
						trigger: 'blur'
					}],
				},
			};
		},
		methods: {
			handleAvatarSuccess(res, file) {
				this.imageUrl = URL.createObjectURL(file.raw);
			},
			submitForm(formName) {
				this.$refs[formName].validate((valid) => {
					if (valid) {
						let fd = new FormData();
						let files1 = this.$refs.uploadCompent.uploadFiles
						console.log(files1)
						fd.append("mypic", files1[0].raw);
						//将对象转换为json类型和文件一起提交到后端
						fd.append('account', this.user.account);
						fd.append('password', this.user.password);
						fd.append('nickname', this.user.nickname);
						fd.append('addr', this.user.addr);
						fd.append('phone', this.user.phone);
						this.$postf(`/api/public/addUser`,fd)
							.then((resp) => {
								if(resp.data.code == 200){
								this.$message({
									type: 'success',
									message: resp.data.msg
								})
								this.$router.push("/fore/home/main")
								}else{
									this.$message({
										type:"error",
										message: resp.data.msg
									})
								}
							}).catch(function(error) {
								console.log(error)
							})
					} else {
						console.log('error submit!!');
						return false;
					}
				})
			},
		},
		computed: {
			
		},
	}
</script>

<style>
	.avatar-uploader .el-upload {
		border: 1px dashed #d9d9d9;
		border-radius: 6px;
		cursor: pointer;
		position: relative;
		overflow: hidden;
	}

	.avatar-uploader .el-upload:hover {
		border-color: #409EFF;
	}

	.avatar-uploader-icon {
		font-size: 28px;
		color: #8c939d;
		width: 30vw;
		height:40vh;
		line-height: 40vh;
		text-align: center;
	}

	.avatar {
		width: 30vw;
		height: 40vh;
		display: block;
	}
</style>