<template>
	<div>
		<div style="text-align: center;margin-top: 15px;"><i class="el-icon-notebook-2" style="color: blueviolet;"></i>
			<span style="color: #3f7fce;font-weight: 600;">请付款:</span>
		</div>
		<hr>
		<table style="margin: auto;">
			<tr>
				<td>订单号</td>
				<td><el-input v-model="order.ordid" size="small" style="width: 40vw;"></el-input></td>
			</tr>
			<tr>
				<td>订单总额</td>
				<td><el-input v-model="order.amount" size="small"></el-input></td>
			</tr>
			<tr>
				<td>姓名</td>
				<td><el-input v-model="order.ship2name" size="small"></el-input></td>
			</tr>
			<tr>
				<td>电话</td>
				<td><el-input v-model="order.ship2phone" size="small"></el-input></td>
			</tr>
			<tr>
				<td>地址</td>
				<td><el-input v-model="order.ship2addr" size="small"></el-input></td>
			</tr>
			<tr>
				<td>付款状态</td>
				<td><el-button type="danger" v-show="order.pay_status ==0" size="small"
						@click="dialogVisible = true">请付款</el-button>
					<el-button type="success" v-show="order.pay_status ==1" size="small">已经付款</el-button>
				</td>
			</tr>
		</table>
		<el-dialog :title="`应付金额:${order.amount}￥`" :visible.sync="dialogVisible" width="30%" 
			center>
			<div style="  display: flex;justify-content: center;align-items: center;">
				<img src="../../../assets/微信图片_20231228203528.jpg" style="width: 30vw;height: 45vh;">
			</div>
			<span slot="footer" class="dialog-footer">
				<el-button @click="dialogVisible = false">取 消</el-button>
				<el-button type="danger" @click="pay()">确认付款</el-button>
			</span>
		</el-dialog>
		<hr>
		<p style="text-align: center;">订单详情</p>
		<el-table style="width: 90%;margin-top: 10px;margin-left: 5%;" :data="order.orderItem" border>
			<el-table-column label="图片">
				<template slot-scope="scope">
					<img :src="'http://127.0.0.1:80/api/public/showimg/'+scope.row.book.pic"
						style="width: 70px;height: 70px;">
				</template>
			</el-table-column>
			<el-table-column prop="book.name" label="商品名称">
			</el-table-column>
			<el-table-column prop="book.price" label="商品价钱">
			</el-table-column>
			<el-table-column prop="num" label="商品数量" width="200">
			</el-table-column>
			<el-table-column label="商品总价">
				<template slot-scope="scope">
					<p>{{scope.row.num*scope.row.book.price}}</p>
				</template>
			</el-table-column>
			<el-table-column label="商品库存" width="200">
				<template slot-scope="scope">
					<p style="color: red;font-weight: 600;" v-show="scope.row.book.stock<=5">{{scope.row.book.stock}}
					</p>
					<p v-show="scope.row.book.stock>5">{{scope.row.book.stock}}</p>
				</template>
			</el-table-column>
		</el-table>
	</div>
</template>

<script>
	export default {
		data() {
			return {
				order: {},
				dialogVisible: false,
				ordid:this.$route.query.ordid
			};
		},
		methods: {
			pay() {
				this.$postx(`/api/userc/order/payOrder/${this.ordid}`)
					.then((resp) => {
						this.dialogVisible = false
						this.findOrder()
						this.$message(
						{
							type:'success',
							message:'付款成功'
						})
					})
			},
			findOrder(){
				this.$get("/api/userc/order/findOne", {
						params: {
							ordid: this.ordid
						}
					})
					.then((resp) => {
						this.order = resp.data.data
					})
			}
		},
		created() {
			this.findOrder()
		}
	}
</script>

