import Vue from 'vue'
import VueRouter from 'vue-router'
import store from '@/store'
import { Message } from "element-ui";
//1 注入插件 
Vue.use(VueRouter)

import APP from "@/App.vue"
import Home from "@/views/fore/home/Home.vue"
import ForeRouterH from "@/views/fore/home/ForeRouterH.vue"
import UserMenu from "@/views/fore/home/UserMenu.vue"
import AdmMenu from "@/views/adm/AdmMenu.vue"
import AdmHomeVue from '../views/adm/AdmHome.vue'
import Typelist1Vue from '../views/adm/Typelist1.vue'
import Typelist2Vue from '../views/adm/Typelist2.vue'
import HotImgVue from '../views/adm/HotImg.vue'
import HotManageVue from '../views/adm/HotManage.vue'
import BookManagerVue from '../views/adm/BookManager.vue'
import BookListVue from '../views/adm/BookList.vue'
import HomeBookListVue from '../views/fore/book/HomeBookList.vue'
import BookMessageVue from '../views/fore/book/BookMessage.vue'
import ForeRouterB from '../views/fore/book/ForeRouterB.vue'
import ForeRouterU from '../views/fore/user/ForeRouterU.vue'
import UserManagerVue from '../views/fore/user/UserManager.vue'
import ForeRouterO from '../views/fore/ord/ForeRouterO.vue'
import MyCartVue from '../views/fore/ord/MyCart.vue'
import CartToOrderVue from '../views/fore/ord/CartToOrder.vue'
import OrderMessageVue from '../views/fore/ord/OrderMessage.vue'
import PayMoneyVue from '../views/fore/ord/PayMoney.vue'
import AdmOrderVue from '../views/adm/AdmOrder.vue'
import UpdatePwdVue from '../views/fore/user/UpdatePwd.vue'
import UpdateHeadVue from '../views/fore/user/UpdateHead.vue'
import UpdateEditVue from '../views/fore/user/UpdateEdit.vue'
import RegisterUserVue from '../views/fore/home/RegisterUser.vue';


const routes = [{
		path: '/fore',
		component: UserMenu,
		children: [{
				path: 'home',
				component: ForeRouterH,
				children: [{
					path: 'main',
					component: Home
				},
				{
					path: 'register',
					component: RegisterUserVue
				}]
			},
			{
				path: 'book',
				component: ForeRouterB,
				children: [{
						path: 'homebooklist',
						component: HomeBookListVue
					},
					{
						path: 'bookmessage',
						name: 'bookmessage',
						component: BookMessageVue
					},
				]
			},

			{
				path: 'user',
				component: ForeRouterU,
				meta: {
					requiresAuth:true,
					requiresUser:true,
				},
				children: [{
					path: 'center',
					name: 'center',
					component: UserManagerVue,
					children: [{
							path: 'pwd',
							name: 'pwd',
							component: UpdatePwdVue
						},
						{
							path: 'head',
							name: 'head',
							component: UpdateHeadVue
						},
						{
							path: 'edit',
							name: 'edit',
							component: UpdateEditVue
						},
					]
				}, ]
			},
			{
				path: 'ord',
				component: ForeRouterO,
				meta: {
					requiresAuth:true,
					requiresUser:true,
				},
				children: [{
						path: 'myCart',
						name: 'myCart',
						component: MyCartVue,
					},
					{
						path: 'carttoorder',
						name: 'carttoorder',
						component: CartToOrderVue,
					},
					{
						path: 'orderMessage',
						name: 'orderMessage',
						component: OrderMessageVue,
					},
					{
						path: 'payMoney',
						name: 'payMoney',
						component: PayMoneyVue,
					},
				]
			},
		]
	},
	{
		path: '/adm',
		component: AdmMenu,
		meta: {
			requiresAuth:true,
			requiresAdm:true,
		},
		children: [{
				path: 'home',
				component: AdmHomeVue
			},
			{
				path: 'typelist1',
				component: Typelist1Vue
			},
			{
				path: 'typelist2',
				component: Typelist2Vue
			},
			{
				path: 'hotimg',
				component: HotImgVue,
			},
			{
				path: 'hmanage',
				name: 'hmanage',
				component: HotManageVue,
			},
			{
				path: 'booklist',
				name: 'booklist',
				component: BookListVue,
			},
			{
				path: 'bmanage',
				name: 'bmanage',
				component: BookManagerVue,
			},
			{
				path: 'orderList',
				name: 'orderList',
				component: AdmOrderVue,
			},
		]
	},
	{
		path: "/",
		redirect: "/fore/home/main",
		component: APP
	}
]


//3 创建router实例 
const router = new VueRouter({
	routes,
})

router.beforeEach((to, from, next) => {
	//to.matched,some() 遍历路由数组routes
	let result = to.matched.some((record) => record.meta.requiresAuth)
	let user = to.matched.some((record) => record.meta.requiresUser)
	let adm = to.matched.some((record) => record.meta.requiresAdm)
	console.log(result)
	if (result) {
		//路由验证
		if (store.state.user.user) {
			if(user){
				if(store.state.user.user.role == 'usr'){
					next()
				}else{
					Message.error({message:"不是买家...无法访问"})
					return
				}	
			}
			if(adm){
				if(store.state.user.user.role == 'adm'){
					next()
				}else{
					Message.error({message:"不是管理员...无法访问"})
					return
				}	
			}
		} else {
			Message.error({message:"未登录....请先登录"})
		}
	} else {
		//不用验证
		next()
	}
})
//4 导出router实例 
export default router