<template>
	<div style="margin-left: 4px;width: 100%;text-align: center;">
		<div style="display: flex;">
			<div style="margin-top: 10px;height: 40px;background-color: #d9ecff;width: 40%;">
				<p style="color: #409EFF;margin-top: 11px;float: left;"><i class="el-icon-s-data"></i>商品列表</p>
			</div>
			<div style="margin-top: 10px;height: 40px;background-color: #d9ecff;width: 60%;">
				<el-button type="primary" style="float: left;" @click="goAdd()"><i class="el-icon-document">添加新的商品</i></el-button>
				<p style="float: right;line-height: 8px;color: #409EFF">支持二层类型</p>
			</div>
		</div>

		<el-table style="width: 100%;margin-top: 10px;" :data="books"
			:header-cell-style="{color: '#FFFFFF',background:'#AAAAAA'}">
			<el-table-column prop="name" label="名称">
			</el-table-column>
			<el-table-column prop="sn" label="编号">
			</el-table-column>
			<el-table-column prop="author" label="作者">
			</el-table-column>
			<el-table-column prop="maker" label="厂家">
			</el-table-column>
			<el-table-column  label="日期">
				<template slot-scope="scope">
					{{formatDate(scope.row.tmake)}}
				</template>
			</el-table-column>
			<el-table-column prop="stock" label="库存">
			</el-table-column>
			<el-table-column label="图片">
				<template slot-scope="scope">
					<img :src="'http://127.0.0.1:80/api/public/showimg/'+scope.row.pic"
						style="width: 70px;height: 70px;">
				</template>
			</el-table-column>
			<el-table-column label="操作">
				<template slot-scope="scope">
					<el-button type="primary" @click="goUpdate(scope.row)">修改</el-button>
				</template>
			</el-table-column>
		</el-table>
		<el-pagination background layout="prev, pager, next" :hide-on-single-page="hidepage" @current-change='current'
			:page-size="pageline" :total="total">
		</el-pagination>

	</div>
</template>

<script>
	export default {
		data() {
			return {
				books: [],
				start: 1,
				total: 0,
				pageline: 6,
				add:true,
				hidepage:false
			};
		},
		computed: {

		},
		methods: {
			current(i) {
				this.start = i
				this.$get("/api/public/book/findAll", {
						params: {
							start: (this.start - 1) * this.pageline,
							pageline: this.pageline,
							typeid:0
						}
					})
					.then((resp) => {
						this.books = resp.data.data.lst
						this.total = resp.data.data.count
						if(this.total<this.pageline){
							this.hidePage = true
						}
					})
			},
			goAdd() {
				this.$router.push({
					name: "bmanage",
					params: {
						add: true
					}
				})
			},
			goUpdate(book) {
				this.$router.push({
					name: "bmanage",
					params: {
						book: book,
						add: false
					}
				})
			},
			formatDate(value) {
				const dateObj = new Date(value)
				const year = dateObj.getFullYear()
				const month = dateObj.getMonth() + 1
				const day = dateObj.getDate()
				return `${year}-${month}-${day}`
			},
			remove(id) {
				var that = this
				this.$get(
					"/api/adm/hot/remove", {
						params: {
							id: id
						}
					}
				).then(function(resp) {
					that.$get("/api/adm/hot/findAll")
						.then((resp) => {
							that.hotimgs = resp.data.data
						})
				})
			}
		},
		created() {
			var that = this;
			this.$get("/api/public/book/findAll", {
					params: {
						start: (this.start - 1) * this.pageline,
						pageline: this.pageline,
						typeid:0
					}
				})
				.then((resp) => {
					this.books = resp.data.data.lst
					this.total = resp.data.data.count
					if(this.total<this.pageline){
						this.hidePage = true
					}
				})

		}
	}
</script>

