<template>
	<div class="mainHotImg">
		<div class="titleHotImg">
			<div class="titleHotImg1">
				<p  v-show="add == true"><i class="el-icon-plus"></i>热度图片添加</p>
				<p  v-show="add == false"><i class="el-icon-edit"></i>热度图片修改</p>
			</div>
			<div class="titleHotImg2">
				<el-link @click="back()" style="color: #409EFF;font-size: 15px;white-space: nowrap;overflow: hidden;"><i
						class="el-icon-back">返回列表</i></el-link>
				<el-link @click="doUpdate()" 
				style="color: #409EFF;font-size: 15px;white-space: nowrap;overflow: hidden;margin-left: 5vw;" ><i class="el-icon-document-checked">保存</i></el-link>
				<p style="margin-left: 5vw;color: #409EFF;white-space: nowrap;overflow: hidden;">类型自定义,获取时指定类型 1=轮播图 2=广告图</p>
			</div>
		</div>
		<div style="display: flex;">
			<div style="margin-top: 5px;margin-left: 4%;width: 30vw;height: 30vw;border: 1px solid gainsboro;">
				<el-image style="width: 100%;height: 100%;" :src="'http://127.0.0.1:80/api/public/showimg/'+hotimg.picture"></el-image>
				<el-upload
				ref="uploadCompent"
				  class="upload-demo"
				  action="/api/public/upload"
				  :on-preview="handlePreview"
				  :on-remove="handleRemove"
				  :file-list="fileList"
				  list-type="picture">
				  <el-button size="small" type="primary">点击上传</el-button>
				</el-upload>
			</div>
			<div style="margin-top: 5px;margin-left: 20%;width: 30%;">
				<div style="display: flex;">
					<div style="width: 30%;"><span style="white-space: nowrap;overflow: hidden;">类型-整数:</span></div>
					<div style="width: 70%;margin-left: 5%;"><el-input style="width: 100%;" size="small" v-model="hotimg.type"></el-input></div>
				</div>
				<div style="display: flex;margin-top: 30px;">
					<div style="width: 30%;"><span style="white-space: nowrap;overflow: hidden;">优先级-整数:</span></div>
					<div style="width: 70%;margin-left: 5%;"><el-input style="width: 100%;" size="small" v-model="hotimg.hot"></el-input></div>
				</div>
				<div style="display: flex;margin-top: 30px;">
					<div style="width: 30%;"><span style="white-space: nowrap;overflow: hidden;">描述:</span></div>
					<div style="width: 70%;margin-left: 5%;"><el-input style="width: 100%;" type="textarea" v-model="hotimg.memo"></el-input></div>
				</div>
			</div>
		</div>


	</div>
</template>

<script>
	export default {
		data() {
			return {
				add: this.$route.params.add,
				hotimg:{id:0},
				 fileList: []
			};
		},
		computed: {

		},
		methods: {
			 handleRemove(file, fileList) {
			        console.log(file, fileList);
			      },
			      handlePreview(file) {
			        console.log(file);
			      },
			back() {
				this.$router.push("/adm/hotimg")
			},
			doUpdate(){
				var that = this
				let files1 = this.$refs.uploadCompent.uploadFiles
				let fd = new FormData();
				console.log(files1[0])
				if(files1 !=  null){
				fd.append('pic', files1[0].raw);
				}
				//将对象转换为json类型和文件一起提交到后端
				fd.append('id', this.hotimg.id);
				fd.append('memo', this.hotimg.memo);
				fd.append('hot', this.hotimg.hot);
				fd.append('type', this.hotimg.type);
				fd.append('picture', this.hotimg.picture);
				this.$postf(
					"/api/adm/hot/update",
					fd
				).then(function(resp) {
				that.$router.push("/adm/hotimg")
				})
			}
		},
		update(){
			
		},
		created() {
			if(this.$route.params.hot != null){
			this.hotimg = this.$route.params.hot
			}
		}
	}
</script>

