<template>
	<div style="margin-left: 4px;width: 100%;">
		<div style="display: flex;">

			<div style="margin-top: 10px;height: 40px;background-color: #d9ecff;width: 40%;">
				<p style="line-height: 8px;color: #409EFF;" v-show="add == true">商品添加</p>
				<p style="line-height: 8px;color: #409EFF;" v-show="add == false">商品修改</p>
			</div>

			<div style="margin-top: 10px;height: 40px;background-color: #d9ecff;width: 60%;display: flex;">
				<el-link @click="back()" style="color: #409EFF;font-size: 15px;"><i
						class="el-icon-back">返回列表</i></el-link>
				<div style="width: 10%;"></div>
				<el-link @click="doUpdate()" style="color: #409EFF;font-size: 15px;"><i
						class="el-icon-document-checked">保存</i></el-link>
				<div style="width: 20%;"></div>
				<p style="line-height: 8px;color: #409EFF;">支持二层类型</p>
			</div>
		</div>

		<div style="display: flex;">
			<div style=" width: 40%;">
				<div style="margin-top: 5px;margin-left: 4%;width: 30vw;height: 30vw;border: 1px solid gainsboro;">
					<el-image style="width: 100%;height: 100%;"
						:src="'http://127.0.0.1:80/api/public/showimg/'+book.pic"></el-image>
					<el-upload ref="uploadCompent" class="upload-demo"
						action="/api/public/upload" :on-preview="handlePreview"
						:on-remove="handleRemove" :file-list="fileList" list-type="picture">
						<el-button size="small" type="primary">点击上传</el-button>
					</el-upload>
				</div>
			</div>
			<div style=" width: 56%;">
				<el-form :model="book" :rules="rules" ref="book" label-width="100px" class="demo-ruleForm">
					<el-form-item label="商品名称:" prop="name" style="margin-left: 80px;">
						<el-input style="width: 100%;" size="small" v-model="book.name"></el-input>
					</el-form-item>
					<el-form-item label="商品序号:" prop="sn" style="margin-left: 80px;">
						<el-input style="width: 100%;" size="small" v-model="book.sn"></el-input>
					</el-form-item>
					<el-form-item label="商品价格:" prop="price" style="margin-left: 80px;">
						<el-input style="width: 100%;" v-model="book.price"></el-input>
					</el-form-item>
					<el-form-item label="商品厂商:" prop="maker" style="margin-left: 80px;">
						<el-input style="width: 100%;" v-model="book.maker"></el-input>
					</el-form-item>
					<el-form-item label="书籍作者:" prop="author" style="margin-left: 80px;">
						<el-input style="width: 100%;" v-model="book.author"></el-input>
					</el-form-item>
					<el-form-item label="出厂时间:" prop="tmake" style="margin-left: 80px;">
						<el-date-picker v-model="book.tmake" type="date" placeholder="选择日期">
						</el-date-picker>
					</el-form-item>
					<el-form-item label="商品库存:" prop="stock" style="margin-left: 80px;">
						<el-input style="width: 100%;" v-model="book.stock"></el-input>
					</el-form-item>
					<el-form-item label="商品类型:" prop="typeid" style="margin-left: 80px;">
						<el-cascader v-model="book.typeid" :options="options" :props="{ expandTrigger: 'click' }"
							@change="handleChange"></el-cascader>
					</el-form-item>
					<el-form-item label="商品详情:" prop="info" style="margin-left: 80px;">
						<el-input style="width: 100%;" :autosize="{ minRows: 2, maxRows: 8}" type="textarea"
							v-model="book.info"></el-input>
					</el-form-item>
				</el-form>
			</div>
		</div>


	</div>
</template>

<script>
	export default {
		data() {
			return {
				add: this.$route.params.add,
				book: {
					id: 0
				},
				fileList: [],
				value: [],
				options: [],
				optionT: {},
				childT: {},
				childsT: [],
				types: [],
				children: [],
				data: [],
				rules: {
					name: [{
						required: true,
						message: '请输入',
						trigger: 'blur'
					}, ],
					sn: [{
						required: true,
						message: '请输入',
						trigger: 'blur'
					}, ],
					maker: [{
						required: true,
						message: '请输入',
						trigger: 'blur'
					}, ],
					author: [{
						required: true,
						message: '请输入',
						trigger: 'blur'
					}, ],
					info: [{
						required: true,
						message: '请输入',
						trigger: 'blur'
					}, ],
				},
			};
		},
		computed: {

		},
		methods: {
			handleRemove(file, fileList) {
				
			},
			handlePreview(file) {
				
			},
			back() {
				this.$router.push("/adm/booklist")
			},
			doUpdate() {
				var that = this
				let files1 = this.$refs.uploadCompent.uploadFiles
				let fd = new FormData()
				if (files1 != null) {
					fd.append('picture', files1[0].raw);
				}
				//将对象转换为json类型和文件一起提交到后端
				fd.append('id', this.book.id);
				fd.append('name', this.book.name);
				fd.append('sn', this.book.sn);
				fd.append('price', this.book.price);
				fd.append('pic', this.book.pic);
				fd.append('maker', this.book.maker);
				fd.append('tmake', new Date(this.book.tmake));
				fd.append('author', this.book.author);
				fd.append('stock', this.book.stock);
				if(this.book.typeid.length != null){
					this.book.typeid = this.book.typeid[this.book.typeid.length-1]
				}
				fd.append('typeid', this.book.typeid);
				fd.append('info', this.book.info);
				if (this.book.name != null &&
					this.book.name != "" &&
					this.book.sn != null &&
					this.book.sn != "" &&
					this.book.maker != null &&
					this.book.maker != "" &&
					this.book.author != null &&
					this.book.author != "" &&
					this.book.info != null &&
					this.book.info != "") {
					this.$postf(
						"/api/adm/book/update",
						fd
					).then(function(resp) {
						that.$router.push("/adm/booklist")
					})
				}
			},
			getTypeList() {
				var that = this;
				this.$get("/api/public/type/findAll")
					.then((resp) => {
						this.data = resp.data.data
						for (let i = 0; i < this.data.length; i++) {
							if (this.data[i].pid === 0) {
								console.log(this.data[i])
								this.types.push(this.data[i]);
							}
						}
					
						for (let x = 0; x < this.types.length; x++) {
							for (let i = 0; i < this.data.length; i++) {
								if (this.data[i].pid == this.types[x].id) {
									this.children.push(this.data[i])
									this.types[x].children = this.children
								}
							}
							this.children = []
						}
		
						this.types.sort((a, b) => {
							return a.prio - b.prio
						})
						for (let i = 0; i < this.types.length; i++) {
							if (this.types[i].children != null) {
							this.types[i].children.sort((a, b) => {
								return a.prio - b.prio
							})
							}
						}
						for (let i = 0; i < this.types.length; i++) {
							this.optionT.value = this.types[i].id
							this.optionT.label = this.types[i].name

							if (this.types[i].children != null) {
								for (let x = 0; x < this.types[i].children.length; x++) {
									this.childT.value = this.types[i].children[x].id
									this.childT.label = this.types[i].children[x].name
									this.childsT.push(this.childT)
									this.childT = {}
								}
								this.optionT.children = this.childsT
								this.childsT = []
							}
							this.options.push(this.optionT)
							this.optionT = []
						}

					})
			},
			handleChange(value) {
				
			}

		},
		update() {

		},
		created() {
			this.getTypeList()
			if (this.$route.params.book != null) {
				this.book = this.$route.params.book
			}
		}
	}
</script>

