const state = {
	user:null,
	lastUser:null,
	remeberPwd:false,
	autoLogin:false
	
}

const mutations = {
	saveUser(state,obj){
		state.user=obj
	},
	saveLastUser(state,obj){
		state.lastUser=obj
	},
	remeberPwdM(state,obj){
		state.remeberPwd=obj
	},
	autoLoginM(state,obj){
		state.autoLogin=obj
	},
	deleteUser(state){
		state.user=null
	},
}

const actions = {
	selWord({state,commit},obj){
		commit("saveUser",obj)
	},
	selLastWord({state,commit},obj){
		commit("saveLastUser",obj)
	},
	remeberPwdA({state,commit},obj){
		commit("remeberPwdM",obj)
	},
	autoLoginA({state,commit},obj){
		commit("autoLoginM",obj)
	},
	outUser({state,commit}){
		commit('deleteUser')
	}
}

export default{
	namespaced:true,
	state,mutations,actions
}